code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            # Color the hollow interior.
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    if out[y][x] == 0:
                        out[y][x] = 2
            # Extend the missing top-edge cell outward, away from the closer side.
            gaps = [x for x in range(c0 + 1, c1) if grid[r0][x] == 0]
            if gaps and r0 > 0:
                x = gaps[0]
                if x - c0 > c1 - x:
                    for xx in range(0, x + 1):
                        if out[r0 - 1][xx] == 0:
                            out[r0 - 1][xx] = 2
                else:
                    for xx in range(x, w):
                        if out[r0 - 1][xx] == 0:
                            out[r0 - 1][xx] = 2
    return out
'''
